// them), and the first official frame the sender does not have yet.
struct Input
{
  std::uint64_t token = 0;
  std::uint64_t cookie = 0;
  std::uint32_t first_frame = 0;
  std::uint32_t next_official = 0;
  std::uint8_t count = 0;
  std::vector<std::uint8_t> records;
};

// Official frames FirstFrame..FirstFrame+Count-1: for each, the records of the player seats in seat order.
struct Official
{
  std::uint64_t key = 0;
  std::uint32_t first_frame = 0;
  std::uint8_t count = 0;
  std::uint32_t player_seats = 0;
  std::vector<std::uint8_t> records;
};

