struct Desync
{
  std::uint64_t key = 0;
  std::uint32_t frame = 0;
};

// This seat has gone silent; its last input stands from now on.
struct SeatLeft
{
  std::uint64_t key = 0;
  std::uint8_t seat = 0;
};

// This seat is its player's again from official frame Frame on: the frames before it are the AI's (a returning seat,
// after its game caught up).
struct SeatBack
{
  std::uint64_t key = 0;
  std::uint8_t seat = 0;
  std::uint32_t frame = 0;
};

// The sender's race is over on official steps before step Frame (its race-over test said so): the race has ended, and
