// A packet the relay sends a game: its body opens with the seat's key (KEY_SIZE bytes).
inline constexpr bool FromRelay(Type type)
{
  return type == Type::Pong ||
         type == Type::Joined ||
         type == Type::Go ||
         type == Type::Official ||
         type == Type::Desync ||
         type == Type::SeatLeft ||
         type == Type::SeatBack;
}

// The version of a packet from another version of the game or relay (none: this version, or no relay packet).
inline std::optional<std::uint8_t> ForeignVersion(const std::uint8_t* data, std::size_t len)
{
  if (len < HEADER_SIZE || data[0] != MARK[0] || data[1] != MARK[1] || data[2] == VERSION)
    return std::nullopt;
  return data[2];
}

// A whole datagram; none for anything malformed or foreign.
inline std::optional<Packet> Decode(const std::uint8_t* data, std::size_t len)
{
  if (len < HEADER_SIZE || data[0] != MARK[0] || data[1] != MARK[1] || data[2] != VERSION)
    return std::nullopt;
  const std::uint8_t* body = data + HEADER_SIZE;
  const std::size_t n = len - HEADER_SIZE;
  switch (static_cast<Type>(data[3]))
  {
  case Type::Ping:
    if (auto p = DecodePing(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Pong:
    if (auto p = DecodePong(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Join:
    if (auto p = DecodeJoin(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Joined:
    if (auto p = DecodeJoined(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Ready:
    if (auto p = DecodeReady(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Go:
    if (auto p = DecodeGo(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Input:
    if (auto p = DecodeInput(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Official:
    if (auto p = DecodeOfficial(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Checksum:
    if (auto p = DecodeChecksum(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Desync:
    if (auto p = DecodeDesync(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::SeatLeft:
    if (auto p = DecodeSeatLeft(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::SeatBack:
    if (auto p = DecodeSeatBack(body, n))
      return Packet{std::move(*p)};
    break;
  case Type::Over:
    if (auto p = DecodeOver(body, n))
      return Packet{std::move(*p)};
    break;
  default:
    break;
  }
  return std::nullopt;
}

inline std::vector<std::uint8_t> Encode(const Packet& packet)
{
  return std::visit([](const auto& p) { return Encode(p); }, packet);
}
